import React from "react";

function UserDashboard({
  candidates = [],
  selectedVotes = {},
  setSelectedVotes,
  handleVoteSubmit,
  electionClosed = false,
}) {
  // Get unique positions dynamically from candidates
  const positions = [...new Set(candidates.map((c) => c.position))];

  const confirmVote = () => {
    if (Object.keys(selectedVotes).length === 0) {
      alert("Please select at least one candidate before voting.");
      return;
    }

    const confirm = window.confirm(
      "Are you sure you want to cast your vote? This action cannot be changed."
    );

    if (confirm) {
      handleVoteSubmit();
    }
  };

  return (
    <div style={styles.page}>
      <div style={styles.container}>
        <h1 style={styles.title}>Student Election 2026</h1>
        <p style={styles.subtitle}>Select one candidate per position</p>

        {electionClosed && (
          <div style={styles.closedBanner}>Election is Closed</div>
        )}

        {positions.map((position) => (
          <div key={position} style={styles.positionCard}>
            <h2 style={styles.positionTitle}>{position}</h2>

            {candidates
              .filter((c) => c.position === position)
              .map((candidate) => (
                <label key={candidate._id} style={styles.candidateRow}>
                  <input
                    type="radio"
                    name={position}
                    value={candidate._id}
                    checked={selectedVotes[position] === candidate._id}
                    onChange={() =>
                      setSelectedVotes({
                        ...selectedVotes,
                        [position]: candidate._id,
                      })
                    }
                    disabled={electionClosed}
                  />

                  <div style={styles.candidateInfo}>
                    {candidate.image && (
                      <img
                        src={`http://localhost:5000/uploads/${candidate.image}`}
                        alt={candidate.name}
                        style={styles.avatar}
                      />
                    )}
                    <span style={styles.candidateName}>
                      {candidate.name}
                    </span>
                  </div>
                </label>
              ))}
          </div>
        ))}

        {!electionClosed && (
          <button style={styles.voteButton} onClick={confirmVote}>
            Vote Cast
          </button>
        )}
      </div>
    </div>
  );
}

export default UserDashboard;

/* ===========================
   STYLES
=========================== */

const styles = {
  page: {
    minHeight: "100vh",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    background: "linear-gradient(to right, #8B0000, #B22222)",
    padding: 20,
  },
  container: {
    width: "100%",
    maxWidth: 750,
    backgroundColor: "#ffffff",
    padding: 35,
    borderRadius: 15,
    boxShadow: "0 15px 40px rgba(0,0,0,0.2)",
  },
  title: {
    textAlign: "center",
    marginBottom: 5,
    fontSize: 26,
    fontWeight: "bold",
  },
  subtitle: {
    textAlign: "center",
    marginBottom: 30,
    color: "#666",
  },
  closedBanner: {
    backgroundColor: "#ffcccc",
    color: "#990000",
    padding: 10,
    textAlign: "center",
    borderRadius: 8,
    marginBottom: 20,
    fontWeight: "bold",
  },
  positionCard: {
    marginBottom: 25,
    padding: 18,
    borderRadius: 12,
    backgroundColor: "#f9f9f9",
    border: "1px solid #eee",
  },
  positionTitle: {
    marginBottom: 15,
    fontSize: 18,
    fontWeight: "600",
  },
  candidateRow: {
    display: "flex",
    alignItems: "center",
    padding: 10,
    borderRadius: 8,
    cursor: "pointer",
    transition: "0.2s",
  },
  candidateInfo: {
    display: "flex",
    alignItems: "center",
    gap: 12,
    marginLeft: 10,
  },
  candidateName: {
    fontSize: 15,
  },
  avatar: {
    width: 45,
    height: 45,
    borderRadius: "50%",
    objectFit: "cover",
    border: "2px solid #ddd",
  },
  voteButton: {
    width: "100%",
    padding: 14,
    marginTop: 15,
    borderRadius: 10,
    border: "none",
    backgroundColor: "#8B0000",
    color: "#fff",
    fontSize: 17,
    fontWeight: "bold",
    cursor: "pointer",
    transition: "0.3s",
  },
};
